--
-- Table structure for table `visit_activities`
--

DROP TABLE IF EXISTS `visit_activities`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `visit_activities` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `patient_visit_id` bigint unsigned NOT NULL,
  `recorded_by` bigint unsigned NOT NULL,
  `activity` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `visit_activities_patient_visit_id_foreign` (`patient_visit_id`),
  KEY `visit_activities_recorded_by_foreign` (`recorded_by`),
  CONSTRAINT `visit_activities_patient_visit_id_foreign` FOREIGN KEY (`patient_visit_id`) REFERENCES `patient_visits` (`id`) ON DELETE CASCADE,
  CONSTRAINT `visit_activities_recorded_by_foreign` FOREIGN KEY (`recorded_by`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=439 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

