--
-- Table structure for table `vital_signs`
--

DROP TABLE IF EXISTS `vital_signs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vital_signs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `sync_uuid` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sync_status` enum('pending','synced','failed') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `sync_origin` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'local',
  `sync_updated_at` timestamp NULL DEFAULT NULL,
  `remote_id` bigint unsigned DEFAULT NULL,
  `patient_visit_id` bigint unsigned NOT NULL,
  `body_temperature` decimal(5,2) NOT NULL,
  `blood_pressure_systolic` int NOT NULL,
  `blood_pressure_diastolic` int NOT NULL,
  `heart_rate` int NOT NULL,
  `respiratory_rate` int NOT NULL,
  `oxygen_saturation` decimal(5,2) NOT NULL,
  `blood_glucose` decimal(8,2) DEFAULT NULL,
  `weight` decimal(6,2) DEFAULT NULL,
  `height` decimal(6,2) DEFAULT NULL,
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `recorded_by` bigint unsigned NOT NULL,
  `recorded_date` datetime NOT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `vital_signs_sync_uuid_unique` (`sync_uuid`),
  KEY `vital_signs_patient_visit_id_index` (`patient_visit_id`),
  KEY `vital_signs_recorded_date_index` (`recorded_date`)
) ENGINE=InnoDB AUTO_INCREMENT=54 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

